/** One path of {@link SHOP_STICKER_PICTOGRAM}. */
export interface ShopStickerPictogramPart {
  /** Path data: absolute M, L, C and Z, in sticker units. */
  readonly d: string;
  /** Fill colour (hex); absent for a stroke-only path. */
  readonly fill?: string;
  /** Outline; absent for a fill-only path. */
  readonly stroke?: {
    /** Stroke colour (hex). */
    readonly color: string;
    /** Stroke width in sticker units. */
    readonly width: number;
    /** Round line joins (otherwise miter). */
    readonly roundJoin?: true;
  };
}

